<?php
namespace App\Http\Controllers;
use App\Models\{HistoricalCohort as Cohort,HistoricalCohortRow as Row,Programme,User};
use App\Support\{HistoricalCohorts as H,DirectoryCatalog,PortalPdf};
use Illuminate\Http\Request;
use Illuminate\Support\Str;
class HistoricalCohortsController extends Controller {
 private function actor(Request $r):User{return H::actor($r->user());}
 private function page(string $name,array $data=[]){return response()->view('historical-cohorts.'.$name,$data)->header('Cache-Control','private, no-store')->header('Referrer-Policy','no-referrer');}
 private function filters(Request $r):array {return $r->validate(['programme'=>'required|integer|min:1','from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d','grace'=>'required|integer|between:0,365','as_of'=>'prohibited','tutor'=>'prohibited']);}
 private function attribution(Request $r):array {return $r->validate(['historical_tutor_id'=>'nullable|integer|min:1','basis'=>'required|in:'.implode(',',H::BASES),'reference'=>'required|string|min:5|max:1000','confirmed'=>'accepted']);}
 public function index(Request $r){$this->actor($r);$r->validate(['page'=>'nullable|integer|min:1']);$cohorts=Cohort::orderByDesc('created_at')->paginate(15);$programmes=Programme::orderBy('name')->get();$approved=Cohort::where('state','Approved')->orderByDesc('approved_at')->limit(100)->get();return $this->page('index',compact('cohorts','programmes','approved'));}
 public function preview(Request $r){$u=$this->actor($r);$d=$this->filters($r);$source=H::capture($u,(int)$d['programme'],$d['from'],$d['to'],(int)$d['grace']);$token=(string)Str::uuid();return $this->page('preview',compact('source','token','d'));}
 public function create(Request $r){$this->actor($r);$d=$this->filters($r);$x=$r->validate(['request_token'=>'required|uuid','source_hash'=>'required|regex:/^[a-f0-9]{64}$/D','reference'=>'required|string|min:5|max:1000','confirmed'=>'accepted']);$c=H::create($r->user(),(int)$r->session()->get('auth_version'),(int)$d['programme'],$d['from'],$d['to'],(int)$d['grace'],$x['source_hash'],$x['request_token'],$x['reference']);return to_route('historical-cohorts.show',$c)->with('status','Historical cohort captured as a draft. Current tutor assignments and all live outcomes are unchanged.');}
 public function show(Request $r,Cohort $cohort){$u=$this->actor($r);$all=H::rows($cohort);$rows=Row::where('cohort_id',$cohort->id)->orderBy('apprentice_id')->paginate(25);$reviewed=collect($all)->filter(fn($row)=>$row->details['attribution']['reviewed'])->count();$staff=User::whereIn('role',[...DirectoryCatalog::STAFF_ROLES,'admin','ceo'])->orderBy('name')->get();return $this->page('show',compact('cohort','rows','reviewed','staff','u'));}
 public function row(Request $r,Cohort $cohort,Row $row){$u=$this->actor($r);H::rows($cohort);abort_unless($row->cohort_id===$cohort->id,404);$staff=User::whereIn('role',[...DirectoryCatalog::STAFF_ROLES,'admin','ceo'])->orderBy('name')->get();return $this->page('row',compact('cohort','row','staff','u'));}
 public function edit(Request $r,Cohort $cohort,Row $row){$this->actor($r);$x=$this->attribution($r);$d=$r->validate(['version'=>'required|integer|min:1','row_version'=>'required|integer|min:1']);H::edit($r->user(),(int)$r->session()->get('auth_version'),$cohort,$row,(int)$d['version'],(int)$d['row_version'],isset($x['historical_tutor_id'])?(int)$x['historical_tutor_id']:null,$x['basis'],$x['reference']);return to_route('historical-cohorts.show',$cohort)->with('status','Historical attribution recorded with evidence. No current staff assignment was changed.');}
 public function batch(Request $r,Cohort $cohort){$this->actor($r);$x=$this->attribution($r);$d=$r->validate(['version'=>'required|integer|min:1','rows'=>'required|array|min:1|max:25','rows.*'=>'required|integer|min:1']);H::editBatch($r->user(),(int)$r->session()->get('auth_version'),$cohort,(int)$d['version'],array_map('intval',$d['rows']),isset($x['historical_tutor_id'])?(int)$x['historical_tutor_id']:null,$x['basis'],$x['reference']);return to_route('historical-cohorts.show',$cohort)->with('status','Selected attributions recorded together. Every selected row retains the evidence reference and needs cohort approval.');}
 public function decide(Request $r,Cohort $cohort){$this->actor($r);$d=$r->validate(['version'=>'required|integer|min:1','action'=>'required|in:approve,reject,withdraw','reference'=>'required|string|min:5|max:1000','ceo_override'=>'nullable|boolean','confirmed'=>'accepted']);H::decide($r->user(),(int)$r->session()->get('auth_version'),$cohort,(int)$d['version'],$d['action'],$d['reference'],(bool)($d['ceo_override']??false));return to_route('historical-cohorts.show',$cohort)->with('status','Historical cohort decision recorded; the captured source and review history are retained.');}
 public function report(Request $r,Cohort $cohort){$report=H::report($this->actor($r),$cohort);return $this->page('report',compact('report','cohort'));}
 public function download(Request $r,Cohort $cohort){$report=H::report($this->actor($r),$cohort);return response()->json($report,200,['Content-Disposition'=>'attachment; filename="GTA-Historical-Cohort-'.$cohort->id.'.json"','Cache-Control'=>'private, no-store','Referrer-Policy'=>'no-referrer']);}
 public function pdf(Request $r,Cohort $cohort){$report=H::report($this->actor($r),$cohort);return PortalPdf::response('pdf.historical-cohort',compact('report'),'GTA-Historical-Cohort-'.$cohort->id);}
 public function compare(Request $r){$u=$this->actor($r);$d=$r->validate(['earlier'=>'required|uuid','later'=>'required|uuid']);$comparison=H::compare($u,Cohort::findOrFail($d['earlier']),Cohort::findOrFail($d['later']));return $this->page('compare',compact('comparison'));}
}
